CREATE TEMP TABLE luna_bundle_component_price_stage (source_kind text, bundle_model_code text, component_model_code text, context_release_price numeric(19,2), context_delivery_price numeric(19,2), default_qty numeric(5,2));
\copy luna_bundle_component_price_stage FROM 'sheet-bundle-component-prices.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8');
INSERT INTO bundle_component (id,bundle_product_id,component_product_code,default_qty,qty_mode,component_kind,component_variant,is_default,created_at,created_by,modified_at,modified_by,deleted_at,deleted_by,is_deleted,context_release_price,context_delivery_price)
SELECT gen_random_uuid(), p.id, s.component_model_code, s.default_qty, 'FOLLOW_SET', CASE WHEN s.source_kind='COMMERCIAL' THEN 'OUTDOOR' ELSE 'ACCESSORY' END, NULL, TRUE, CURRENT_TIMESTAMP, 'codex-luna-1241', CURRENT_TIMESTAMP, 'codex-luna-1241', NULL, NULL, FALSE, s.context_release_price, s.context_delivery_price FROM luna_bundle_component_price_stage s JOIN products p ON p.model_code=s.bundle_model_code AND p.is_deleted=FALSE LEFT JOIN bundle_component bc ON bc.bundle_product_id=p.id AND bc.component_product_code=s.component_model_code AND bc.is_deleted=FALSE WHERE bc.id IS NULL;
UPDATE bundle_component bc SET context_release_price=s.context_release_price, context_delivery_price=s.context_delivery_price, default_qty=s.default_qty, modified_at=CURRENT_TIMESTAMP, modified_by='codex-luna-1241' FROM luna_bundle_component_price_stage s JOIN products p ON p.model_code=s.bundle_model_code AND p.is_deleted=FALSE WHERE bc.bundle_product_id=p.id AND bc.component_product_code=s.component_model_code AND bc.is_deleted=FALSE;
